body.script:
(function(){
  var NS = 'http://www.w3.org/1999/xhtml', $ = function(i){ return document.getElementById(i); };
  var search = $('search'), count = $('count'), empty = $('empty'), toast = $('toast'), sheet = $('sheet'), sheetUrl = $('sheetUrl');
  var groups = [].slice.call(document.querySelectorAll('.group'));

  function say(m){ toast.textContent = m; toast.classList.add('show'); clearTimeout(say.t); say.t = setTimeout(function(){ toast.classList.remove('show'); }, 1500); }
  function flash(b){ b.textContent = 'copied'; b.classList.add('ok'); clearTimeout(b.t); b.t = setTimeout(function(){ b.textContent = 'copy'; b.classList.remove('ok'); }, 1200); }
  function manual(t){ sheetUrl.value = t; sheet.classList.add('show'); sheetUrl.focus(); sheetUrl.select(); try{ sheetUrl.setSelectionRange(0, t.length); }catch(e){} }
  function copy(t, b){
    var ok = function(){ flash(b); say('copied (ﾉ◕ヮ◕)ﾉ'); };
    if(navigator.clipboard && navigator.clipboard.writeText){ navigator.clipboard.writeText(t).then(ok, function(){ manual(t); }); }
    else manual(t);
  }
  $('sheetX').addEventListener('click', function(){ sheet.classList.remove('show'); });

  [].forEach.call(document.querySelectorAll('.acts'), function(box){
    var t = box.parentNode.querySelector('.u').textContent, b = document.createElementNS(NS, 'button');
    b.setAttribute('type', 'button'); b.setAttribute('class', 'btn'); b.textContent = 'copy';
    b.addEventListener('click', function(){ copy(t, b); });
    box.insertBefore(b, box.firstChild);
  });

  function update(){
    var q = (search.value || '').trim().toLowerCase(), g = 0, l = 0;
    groups.forEach(function(grp){
      var hitName = !q || grp.querySelector('.gn').textContent.toLowerCase().indexOf(q) > -1, n = 0;
      [].forEach.call(grp.querySelectorAll('.li'), function(it){
        var hit = hitName || it.querySelector('.u').textContent.toLowerCase().indexOf(q) > -1;
        it.classList.toggle('hidden', !hit); if(hit) n++;
      });
      grp.querySelector('.pill').textContent = n;
      grp.classList.toggle('hidden', !n);
      if(q && n) grp.open = true;
      if(n){ g++; l += n; }
    });
    count.innerHTML = '<b>' + g + '</b> groups, <b>' + l + '</b> links';
    empty.classList.toggle('show', !g);
  }
  search.addEventListener('input', update);
  document.addEventListener('keydown', function(e){
    if(e.key === '/' && document.activeElement !== search){ e.preventDefault(); search.focus(); search.select(); }
    else if(e.key === 'Escape'){ sheet.classList.remove('show'); if(search.value){ search.value = ''; update(); } }
  });
})();
